CREATE OR REPLACE FUNCTION public.enforce_student_user_role()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    linked_user_role TEXT;
BEGIN
    IF NEW.user_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- Serialize linking against a concurrent role change. The foreign key will
    -- report a missing user; this trigger owns only the cross-table role rule.
    SELECT role
    INTO linked_user_role
    FROM users
    WHERE id = NEW.user_id
    FOR UPDATE;

    IF linked_user_role IS NOT NULL AND linked_user_role <> 'STUDENT' THEN
        RAISE EXCEPTION 'students.user_id must reference a user with role STUDENT'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'chk_students_user_role';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_phase1_application()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.status<>'DRAFT' OR NEW.version<>1 OR NEW.submitted_at IS NOT NULL THEN
      RAISE EXCEPTION 'Applications must start as version-one Drafts' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Applications are retained' USING ERRCODE='55000'; END IF;
  IF NEW.id<>OLD.id OR NEW.student_id<>OLD.student_id OR NEW.cycle_id<>OLD.cycle_id THEN
    RAISE EXCEPTION 'Application identity is immutable' USING ERRCODE='55000';
  END IF;
  IF OLD.status='SUBMITTED' AND NOT (NEW.status='NEEDS_REVISION' AND NEW.payload=OLD.payload
    AND EXISTS(SELECT 1 FROM phase1_reviews r JOIN phase1_submissions s ON s.id=r.submission_id
      WHERE r.application_id=OLD.id AND r.status='RETURNED' AND s.application_version=OLD.version)) THEN
    RAISE EXCEPTION 'Submitted content can only be returned by scoped review' USING ERRCODE='55000';
  END IF;
  IF NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Application version must advance once' USING ERRCODE='23514'; END IF;
  IF NEW.status='SUBMITTED' AND NOT EXISTS(SELECT 1 FROM phase1_submissions
    WHERE application_id=NEW.id AND application_version=NEW.version) THEN
    RAISE EXCEPTION 'Submission snapshot required' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_phase1_attachment()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE app UUID;
BEGIN
  app:=CASE WHEN TG_OP='DELETE' THEN OLD.application_id ELSE NEW.application_id END;
  IF TG_OP='UPDATE' AND (NEW.application_id<>OLD.application_id OR NEW.kind<>OLD.kind) THEN
    RAISE EXCEPTION 'Attachment cannot move applications' USING ERRCODE='55000';
  END IF;
  PERFORM 1 FROM phase1_applications WHERE id=app AND status IN ('DRAFT','NEEDS_REVISION') FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Submitted attachments are immutable' USING ERRCODE='55000'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.lock_phase1_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE target UUID; prefix TEXT;
BEGIN
  IF TG_TABLE_NAME='phase1_academic_profiles' THEN
    target:=CASE WHEN TG_OP='DELETE' THEN OLD.student_id ELSE NEW.student_id END;
    prefix:='phase1:profile:';
  ELSIF TG_TABLE_NAME='rounds' THEN
    target:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;
    prefix:='phase1:cycle:';
  ELSE
    target:=CASE WHEN TG_OP='DELETE' THEN OLD.cycle_id ELSE NEW.cycle_id END;
    prefix:='phase1:cycle:';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(prefix || target::text,0));
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$
